if(!customElements.get('workspace-workbench'))customElements.define('workspace-workbench',WorkspaceWorkbench);














(function(){
  if(typeof window==='undefined' || !window.customElements) return;
  function nameFrom(path){return String(path||'').split(/[\\/]/).filter(Boolean).pop()||path||'artifact';}
  function typeFrom(path,kind){if(kind==='Directory')return'DIR';const m=String(path||'').toLowerCase().match(/\.([a-z0-9]+)$/);return m?m[1].toUpperCase():'FILE';}
  function artifactUrl(sessionKey,item){return '/api/web-modules/Workspace/session-artifact?sessionKey='+encodeURIComponent(sessionKey||'')+'&owningSessionKey='+encodeURIComponent(item.owningSessionKey||'')+'&path='+encodeURIComponent(item.relativePath||'');}
  function mapSummary(sessionKey,summary){
    const files=(summary.artifacts||[]).filter(x=>x.kind!=='Directory').map((x,i)=>({id:'summary-'+i,name:nameFrom(x.relativePath),type:typeFrom(x.relativePath,x.kind),source:x.owningSessionKey,path:x.relativePath,href:artifactUrl(sessionKey,x),reason:'Workspace artifact',excerpt:x.relativePath,when:'recent',updated:i,pinned:i===0}));
    const profile=summary.profile||{};
    const skills=[{id:'sales',name:profile.pinnedSkillName||profile.pinnedSkillPrototype||'MarketingWebsiteSalesSkill',prototype:profile.pinnedSkillPrototype||'MarketingWebsiteSalesSkill',category:'Pinned parent skill',description:'Pinned workspace skill.',actions:[['Create pharmacy growth proposal deck','ToCreatePharmacyGrowthProposalDeckSkill',''],['Create website growth proposal deck','ToCreateWebsiteGrowthProposalDeckSkill',''],['Create website analysis sales packet','ToCreateWebsiteAnalysisSalesPacketSkill',''],['Build demo website from analysis','ToBuildDemoWebsiteFromAnalysisSkill','']]}];
    const actions=skills[0].actions.map((a,i)=>({id:String(i),name:a[0],skill:skills[0].name,action:a[1],kind:'Prompt action',variables:0,uses:0,updated:'recent',description:a[0],fields:[a[1]]}));
    return {workspaceKey:summary.workspaceKey,files,importantFiles:files.filter(x=>x.pinned),pinnedFiles:files.filter(x=>x.pinned),pins:files.filter(x=>x.pinned),skills,actions,sources:(summary.sessions||[]).map((s,i)=>['source-'+i,s.sessionKey,s.sessionKey,0,s.isCurrent?'Primary':'Available']),sessionSourceCards:[]};
  }
  window.BuffalyWorkspaceWorkbench={
    open:function(sessionKey,summary){
      window.WORKSPACE_WORKBENCH_DATA=mapSummary(sessionKey,summary||{}); FILES=window.WORKSPACE_WORKBENCH_DATA.files||[]; SKILLS=window.WORKSPACE_WORKBENCH_DATA.skills||[]; TEMPLATES=window.WORKSPACE_WORKBENCH_DATA.actions||[]; SOURCES=window.WORKSPACE_WORKBENCH_DATA.sources||[]; SESSION_SOURCE_CARDS=window.WORKSPACE_WORKBENCH_DATA.sessionSourceCards||[]; try{ window.localStorage && window.localStorage.setItem('WorkspaceWorkbenchPins:'+window.WORKSPACE_WORKBENCH_DATA.workspaceKey, JSON.stringify((window.WORKSPACE_WORKBENCH_DATA.files||[]).slice(0,1).map(function(x){return x.id;}))); }catch{}
      let el=document.querySelector('workspace-workbench');
      if(!el){ el=document.createElement('workspace-workbench'); document.body.appendChild(el); }
      if(!el.started){ el.configure({workspace:{key:(summary&&summary.workspaceKey)||'workspace',sessionKey:sessionKey,name:(summary&&summary.workspaceName)||'Workspace',description:'Find shared artifacts, pinned material, skills, and source sessions.'}}); el.start(); }
      return el;
    }
  };
})();



